"use strict";
import { SharedEventName } from "@uniswap/analytics-events";
import { getTokenExploreURL } from "graphql/data/util";
import { useState } from "react";
import { ChevronDown } from "react-feather";
import { useNavigate } from "react-router-dom";
import { AnimatedPopover, Flex, Popover, Text } from "ui/src";
import { CheckCircleFilled } from "ui/src/components/icons";
import Trace from "uniswap/src/features/telemetry/Trace";
import { getChainUrlParam } from "utils/chainParams";
export default function NavigatePageDropdown({
  Pages,
  chainInfo,
  currentTab
}) {
  const [isOpen, setIsOpen] = useState(false);
  const [activePage, setActivePage] = useState(Pages[currentTab].title);
  const navigate = useNavigate();
  return <Flex display="none" $md={{ display: "flex" }} data-testid="explore-navbar">
      <Popover allowFlip onOpenChange={setIsOpen}>
        <Popover.Trigger
    py={"$spacing12"}
    px={"$spacing12"}
    gap={"$gap8"}
    borderWidth={1}
    borderColor={"$surface3"}
    justifyContent="space-between"
    alignItems="center"
    borderRadius={"$rounded12"}
    cursor="pointer"
  >
          <Flex row gap={"$gap4"} alignItems="center">
            <Text variant="buttonLabel3">{activePage}</Text>
            <Flex transform={isOpen ? "rotate(180deg)" : "rotate(0deg)"}>
              <ChevronDown size={16} />
            </Flex>
          </Flex>
        </Popover.Trigger>
        <AnimatedPopover isOpen={isOpen} marginTop={"$spacing8"}>
          <Flex $md={{ pb: "$spacing24" }}>
            {Pages.map(({ title, loggingElementName, key }, index) => {
    const url = getTokenExploreURL({
      tab: key,
      chainUrlParam: chainInfo ? getChainUrlParam(chainInfo.id) : ""
    });
    return <Trace
      logPress
      eventOnTrigger={SharedEventName.NAVBAR_CLICKED}
      element={loggingElementName}
      key={index}
    >
                  <Popover.Close asChild>
                    <Flex
      row
      py={"$spacing16"}
      hoverStyle={{ backgroundColor: "$surface2" }}
      cursor="pointer"
      alignItems="center"
      gap={"$gap12"}
      px={"$spacing12"}
      width={"100%"}
      borderRadius={"$rounded12"}
      onPress={() => {
        navigate(url);
        setActivePage(title);
      }}
    >
                      <Text variant="buttonLabel3">{title}</Text>
                      {currentTab === index && <CheckCircleFilled size={16} />}
                    </Flex>
                  </Popover.Close>
                </Trace>;
  })}
          </Flex>
        </AnimatedPopover>
      </Popover>
    </Flex>;
}
